#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.GameContent.Buffs.Entities;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Detections;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine.Buffs;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;

namespace MVZ2.GameContent.Buffs.Contraptions
{
    [AutoBuffDefinition(VanillaBuffNames.Contraption.onbashiraFall)]
    public class OnbashiraFallBuff : BuffDefinition
    {
        public OnbashiraFallBuff(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var contraption = buff.GetEntity();
            if (contraption == null)
                return;

            float damageMultiplier = GetDamageMultiplier(buff);
            var damage = contraption.GetDamage() * damageMultiplier;

            smashBuffer.Clear();
            smashDetector.DetectMultiple(contraption, smashBuffer);
            var buffSource = new BuffSourceReference(contraption, buff);
            foreach (var target in smashBuffer)
            {
                var other = target.Entity;
                if (!CanSmash(contraption, other))
                    continue;
                if (!CollisionCheckerBuff.IsEnter(other, buffSource))
                    continue;
                target.TakeDamage(damage, new DamageEffectList(VanillaDamageEffects.IMPACT, VanillaDamageEffects.MUTE, VanillaDamageEffects.DAMAGE_BODY_AFTER_ARMOR_BROKEN), contraption);
            }

            if (contraption.IsOnGround)
            {
                contraption.DestroyConflictGridEntities();
                buff.Remove();
            }
        }
        public static bool CanSmash(Entity contraption, Entity other)
        {
            return other != contraption && other.IsVulnerableEntity() && contraption.IsHostile(other);
        }
        public static float GetDamageMultiplier(Buff buff) => buff.GetProperty<float>(PROP_DAMAGE_MULTIPLIER);
        public static void SetDamageMultiplier(Buff buff, float value) => buff.SetProperty(PROP_DAMAGE_MULTIPLIER, value);
        public static readonly VanillaBuffPropertyMeta<float> PROP_DAMAGE_MULTIPLIER = new VanillaBuffPropertyMeta<float>("damage_multiplier", 18);
        private List<IEntityCollider> smashBuffer = new List<IEntityCollider>();
        private Detector smashDetector = new OnbashiraFallDetector();
    }
}
